mapper.select:
SELECT u.id AS userId, u.user_code AS userCode, u.gender AS gender, u.age AS age, u.province AS province, s.segment_name AS segmentName, COALESCE(p.total_payment_amount, 0) AS totalPaymentAmount, COALESCE(p.total_order_count, 0) AS totalOrderCount FROM user_cluster c JOIN ecommerce_user u ON u.id = c.user_id LEFT JOIN user_profile_summary p ON p.user_id = u.id LEFT JOIN user_segment s ON s.user_id = u.id WHERE c.cluster_id = #{cluster}
ORDER BY totalPaymentAmount ${orderDir == 'asc' ? 'ASC' : 'DESC'}
ORDER BY totalOrderCount ${orderDir == 'asc' ? 'ASC' : 'DESC'}, totalPaymentAmount DESC
ORDER BY totalPaymentAmount DESC
LIMIT #{limit} OFFSET #{offset}
